import { readFileSync } from 'node:fs'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import fixtures from './__fixtures__/horizons.json'
import { DAY_MS } from './constants.ts'
import type { EphemTableMeta } from './ephemTable.ts'
import {
  bodyFixedEphemeris,
  ephemerisSeries,
  ephemerisSource,
  iauEphemeris,
  setEphemerisTable,
  skyAt,
} from './ephemeris.ts'
import { wrap180 } from './frames.ts'

describe('IAU model vs JPL Horizons (DE441, MEAN_ME)', () => {
  // Reference values generated by `npm run validate` (scripts/data/validate-horizons.ts).
  it.each(fixtures.map((f) => [`${f.site} ${f.date} ${f.body}`, f] as const))(
    '%s agrees within 0.02°',
    (_, f) => {
      const sky = skyAt(new Date(`${f.date}:00Z`), { lat: f.lat, lon: f.lon, heightM: f.heightM })
      const body = sky[f.body as 'sun' | 'earth']
      expect(Math.abs(body.el - f.el)).toBeLessThan(0.02)
      expect(Math.abs(wrap180(body.az - f.az)) * Math.cos((f.el * Math.PI) / 180)).toBeLessThan(
        0.02,
      )
    },
  )
})

describe('ephemeris with the published DE441 table vs JPL Horizons', () => {
  const meta = JSON.parse(readFileSync('public/data/ephem/de441.json', 'utf8')) as EphemTableMeta
  const buf = readFileSync('public/data/ephem/de441.bin')
  const table = { ...meta, data: new Float32Array(new Uint8Array(buf).buffer) }
  beforeAll(() => setEphemerisTable(table))
  afterAll(() => setEphemerisTable(null))

  it('covers 2026-2030 and is used there, IAU outside', () => {
    expect(ephemerisSource(Date.UTC(2026, 0, 1))).toBe('horizons')
    expect(ephemerisSource(Date.UTC(2030, 11, 31, 12))).toBe('horizons')
    expect(ephemerisSource(Date.UTC(2032, 0, 1))).toBe('iau')
    const outside = new Date(Date.UTC(2035, 5, 1))
    expect(bodyFixedEphemeris(outside)).toEqual(iauEphemeris(outside))
  })

  // Measured by `npm run validate`: ≤ 1.4″ at every site; 0.001° = 3.6″ leaves headroom.
  it.each(fixtures.map((f) => [`${f.site} ${f.date} ${f.body}`, f] as const))(
    '%s agrees within 0.001°',
    (_, f) => {
      const sky = skyAt(new Date(`${f.date}:00Z`), { lat: f.lat, lon: f.lon, heightM: f.heightM })
      const body = sky[f.body as 'sun' | 'earth']
      expect(Math.abs(body.el - f.el)).toBeLessThan(0.001)
      expect(Math.abs(wrap180(body.az - f.az)) * Math.cos((f.el * Math.PI) / 180)).toBeLessThan(
        0.001,
      )
    },
  )
})

describe('lunar geometry sanity checks', () => {
  const pole = { lat: -90 + 1e-6, lon: 0, heightM: 0 }

  it('at the south pole the Sun stays within ~1.6° of the horizon all year', () => {
    let min = 90
    let max = -90
    for (let d = 0; d < 365; d += 0.5) {
      const el = skyAt(new Date(Date.UTC(2026, 0, 1) + d * DAY_MS), pole).sun.el
      min = Math.min(min, el)
      max = Math.max(max, el)
    }
    expect(max).toBeLessThan(1.7)
    expect(min).toBeGreaterThan(-1.7)
    expect(max - min).toBeGreaterThan(2.5)
  })

  it('the Earth never rises on the far side', () => {
    for (let d = 0; d < 60; d += 1) {
      const sky = skyAt(new Date(Date.UTC(2026, 0, 1) + d * DAY_MS), {
        lat: 0,
        lon: 180,
        heightM: 0,
      })
      expect(sky.earth.el).toBeLessThan(-75)
    }
  })

  it('the Earth hangs near the zenith of the sub-Earth point, ~1.9° wide', () => {
    const sky = skyAt(new Date(Date.UTC(2026, 5, 1)), { lat: 0, lon: 0, heightM: 0 })
    expect(sky.earth.el).toBeGreaterThan(80)
    expect(sky.earth.radiusDeg * 2).toBeGreaterThan(1.8)
    expect(sky.earth.radiusDeg * 2).toBeLessThan(2.1)
    expect(sky.sun.radiusDeg).toBeCloseTo(0.267, 2)
  })

  it('a full Moon on Earth is a "new Earth" from the Moon', () => {
    // Full Moon of 2026-05-31.
    const sky = skyAt(new Date(Date.UTC(2026, 4, 31, 8, 45)), { lat: 0, lon: 0, heightM: 0 })
    expect(sky.earthPhase).toBeLessThan(0.02)
  })

  it('the shared series matches the direct computation', () => {
    const start = Date.UTC(2026, 2, 1)
    const series = ephemerisSeries(start, 3_600_000, 3)
    const direct = skyAt(new Date(start + 2 * 3_600_000), { lat: 0, lon: 0, heightM: 0 })
    const sun = Array.from(series.data.subarray(12, 15))
    const dist = Math.hypot(...sun)
    expect(dist).toBeGreaterThan(1.4e8)
    expect(direct.sun.dist).toBeGreaterThan(1.4e8)
  })
})
